#!/usr/bin/env python3
"""Extract literal Brotli tables, checking the immutable source provenance."""
import argparse
import ast
import hashlib
import json
from pathlib import Path
import re
import subprocess

ROOT = Path(__file__).resolve().parent.parent
SOURCE = ROOT / "upstream/libjxl/third_party/brotli"
NOTICE = """// Copyright 2009, 2010, 2013-2016 by the Brotli Authors.
// Distributed under the MIT license in licenses/BROTLI-MIT.txt.
// Generated by tools/generate_brotli_tables.py from the pinned source literals.
// Source hashes: tools/brotli_tables_sources.json. Do not edit by hand.

"""


def uncomment(text):
    return re.sub(r"/\*.*?\*/", "", text, flags=re.S)


def body(text, name):
    pattern = rf"\b{re.escape(name)}\s*\[[^]]*\]\s*=\s*\{{(.*?)\}};"
    match = re.search(pattern, uncomment(text), re.S)
    assert match, name
    return match[1]


def numbers(text):
    tokens = re.findall(r"-?0[xX][\da-fA-F]+|-?\d+", text)
    return [int(n, 0) if "x" in n.lower() else int(n) for n in tokens]


def array(name, values, kind):
    rows = [", ".join(str(v) for v in values[i:i+16]) + ","
            for i in range(0, len(values), 16)]
    return (f"pub static {name}: [{kind}; {len(values)}] = [\n" +
            "\n".join("    " + row for row in rows) + "\n];\n\n")


def outputs():
    provenance = json.loads((ROOT / "tools/brotli_tables_sources.json").read_text())
    assert provenance["pin"] == "db24a98aed38a16de78cc05ca15cdd8dc2a0d92d"
    for name, digest in provenance["files"].items():
        assert hashlib.sha256((SOURCE / name).read_bytes()).hexdigest() == digest, name
    read = lambda name: (SOURCE / name).read_text()
    dictionary = bytes(numbers(body(read("c/common/dictionary_inc.h"), "kBrotliDictionaryData")))
    assert dictionary == (SOURCE / "c/common/dictionary.bin").read_bytes()
    assert len(dictionary) == 122784
    text = NOTICE
    text += 'pub static DICTIONARY_DATA: [u8; 122784] = *include_bytes!("dictionary.bin");\n\n'
    context = numbers(body(read("c/common/context.c"), "_kBrotliContextLookupTable"))
    assert len(context) == 2048
    text += array("CONTEXT_LOOKUP", context, "u8")
    prefix = body(read("c/dec/prefix_inc.h"), "kCmdLut")
    entries = [numbers(entry) for entry in re.findall(r"\{([^{}]*)\}", prefix)]
    assert len(entries) == 704 and all(len(entry) == 6 for entry in entries)
    text += "#[repr(C)]\n#[derive(Clone, Copy, Debug, PartialEq, Eq)]\npub struct CmdLutElement {\n"
    fields = ["insert_len_extra_bits", "copy_len_extra_bits", "distance_code", "context", "insert_len_offset", "copy_len_offset"]
    for field, kind in zip(fields, ["u8", "u8", "i8", "u8", "u16", "u16"]):
        text += f"    pub {field}: {kind},\n"
    text += "}\n\npub static CMD_LUT: [CmdLutElement; 704] = [\n"
    for entry in entries:
        text += "    CmdLutElement { " + ", ".join(f"{field}: {value}" for field, value in zip(fields, entry)) + " },\n"
    text += "];\n\n"
    transform = read("c/common/transform.c")
    prefix_text = re.search(r"kPrefixSuffix\[217\]\s*=\s*(.*?);", uncomment(transform), re.S)[1]
    strings = re.findall(r'"(?:[^"\\]|\\.)*"', prefix_text)
    prefix_bytes = b"".join(ast.literal_eval("b" + piece) for piece in strings) + b"\0"
    assert len(prefix_bytes) == 217
    text += array("PREFIX_SUFFIX", list(prefix_bytes), "u8")
    text += array("PREFIX_SUFFIX_MAP", numbers(body(transform, "kPrefixSuffixMap")), "u16")
    names = re.findall(r"\b(BROTLI_TRANSFORM_\w+)\s*=", read("c/common/transform.h"))
    assert len(names) == 23
    transforms = body(transform, "kTransformsData")
    for i, name in sorted(enumerate(names), key=lambda pair: -len(pair[1])):
        transforms = re.sub(rf"\b{name}\b", str(i), transforms)
    assert not re.search(r"BROTLI_", transforms)
    triples = numbers(transforms)
    assert len(triples) == 121 * 3
    text += array("TRANSFORMS_DATA", triples, "u8")
    formatted = subprocess.run(["rustfmt", "--edition", "2024"], input=text,
                               text=True, capture_output=True, check=True).stdout
    return {ROOT / "src/brotli/tables.rs": formatted.encode(),
            ROOT / "src/brotli/dictionary.bin": dictionary}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    for path, contents in outputs().items():
        if args.check:
            assert path.read_bytes() == contents, path
        else:
            path.write_bytes(contents)


if __name__ == "__main__":
    main()
